// The AssemblyScript types the hood's declarations mention. A plugin writes
// number and boolean; these only make the declarations readable to tsc.
type i8 = number;
type i16 = number;
type i32 = number;
type i64 = number;
type isize = number;
type u8 = number;
type u16 = number;
type u32 = number;
type u64 = number;
type usize = number;
type f32 = number;
type f64 = number;
type bool = boolean;
type StaticArray<T> = T[];
